      SimpleDateFormat format = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
      format.setLenient(false);

      Date thisDeparture = format.parse(getTrip().getDepartureTime());
      Date thisArrival = format.parse(getTrip().getArrivalTime());
